use crate::ast::{Expr,Op,Stmt,Type,Value};
#[derive(Debug,Clone,PartialEq)]pub enum Instruction{Const{dest:String,value:Value,ty:Type},Load{dest:String,name:String,ty:Type},Store{name:String,value:String,ty:Type},Binary{dest:String,op:Op,left:String,right:String,ty:Type},Call{dest:String,name:String,args:Vec<String>,ty:Type},Index{dest:String,target:String,index:String,ty:Type},Aggregate{dest:String,ty:Type},Print{value:String},Assert{value:String},Return(Option<String>),Label(String),Branch{condition:String,then_label:String,else_label:String}}
#[derive(Debug,Clone,PartialEq)]pub struct IrFunction{pub name:String,pub instructions:Vec<Instruction>}
#[derive(Debug,Clone,PartialEq)]pub struct IrProgram{pub functions:Vec<IrFunction>}
pub struct Lowerer{next:usize,main:IrFunction,variables:std::collections::HashMap<String,Type>,functions:std::collections::HashMap<String,Type>}
impl Lowerer{pub fn lower(root:&Stmt)->IrProgram{let mut l=Self{next:0,main:IrFunction{name:"main".into(),instructions:Vec::new()},variables:std::collections::HashMap::new(),functions:std::collections::HashMap::new()};l.collect(root);l.stmt(root);IrProgram{functions:vec![l.main]}}fn collect(&mut self,s:&Stmt){match s{Stmt::Block(xs)=>for x in xs{self.collect(x)},Stmt::Function{name,return_type,..}=>{self.functions.insert(name.clone(),return_type.clone().unwrap_or(Type::Unknown));},_=>{}}}fn temp(&mut self)->String{let n=format!("%{}",self.next);self.next+=1;n}fn expr(&mut self,x:&Expr)->String{match x{Expr::Literal(v,_)=>{let d=self.temp();self.main.instructions.push(Instruction::Const{dest:d.clone(),value:v.clone(),ty:infer(v)});d},Expr::Variable(n,_)=>{let d=self.temp();self.main.instructions.push(Instruction::Load{dest:d.clone(),name:n.clone(),ty:self.variables.get(n).cloned().unwrap_or(Type::Unknown)});d},Expr::Binary{left,op,right,..}=>{let l=self.expr(left);let r=self.expr(right);let d=self.temp();self.main.instructions.push(Instruction::Binary{dest:d.clone(),op:*op,left:l,right:r,ty:Type::Unknown});d},Expr::Call{name,arguments,..}=>{let args=arguments.iter().map(|x|self.expr(x)).collect();let d=self.temp();self.main.instructions.push(Instruction::Call{dest:d.clone(),name:name.clone(),args,ty:self.functions.get(name).cloned().unwrap_or(Type::Unknown)});d},Expr::Index{target,index,..}=>{let t=self.expr(target);let i=self.expr(index);let d=self.temp();self.main.instructions.push(Instruction::Index{dest:d.clone(),target:t,index:i,ty:Type::Unknown});d},Expr::Unary{expr,..}=>self.expr(expr),Expr::Array(xs,_)=>{for x in xs{let _=self.expr(x);}let d=self.temp();self.main.instructions.push(Instruction::Aggregate{dest:d.clone(),ty:Type::Array(Box::new(Type::Unknown))});d},Expr::Map(xs,_)=>{for (_,x) in xs{let _=self.expr(x);}let d=self.temp();self.main.instructions.push(Instruction::Aggregate{dest:d.clone(),ty:Type::Map(Box::new(Type::String),Box::new(Type::Unknown))});d}}}fn stmt(&mut self,s:&Stmt){match s{Stmt::Block(xs)=>for x in xs{self.stmt(x)},Stmt::Let{name,annotation,value,..}=>{let v=self.expr(value);let ty=annotation.clone().unwrap_or(Type::Unknown);self.variables.insert(name.clone(),ty.clone());self.main.instructions.push(Instruction::Store{name:name.clone(),value:v,ty})},Stmt::Assign{name,value,..}=>{let v=self.expr(value);let ty=self.variables.get(name).cloned().unwrap_or(Type::Unknown);self.main.instructions.push(Instruction::Store{name:name.clone(),value:v,ty})},Stmt::Print(x)=>{let v=self.expr(x);self.main.instructions.push(Instruction::Print{value:v})},Stmt::Assert(x)=>{let v=self.expr(x);self.main.instructions.push(Instruction::Assert{value:v})},Stmt::Return{value,..}=>{let v=match value{Some(x)=>Some(self.expr(x)),None=>None};self.main.instructions.push(Instruction::Return(v))},Stmt::Conditional{condition,then_branch,..}=>{let c=self.expr(condition);let l=self.temp();self.main.instructions.push(Instruction::Branch{condition:c,then_label:l.clone(),else_label:format!("{}else",l)});for x in then_branch{self.stmt(x)}},Stmt::RepeatLoop{body,..}=>for x in body{self.stmt(x)},Stmt::Function{..}|Stmt::CreateWindow{..}=>{}}}}
fn infer(v:&Value)->Type{match v{Value::Number(n)=>if n.fract()==0.0{Type::Int}else{Type::Float},Value::Boolean(_)=>Type::Bool,Value::String(_)=>Type::String,Value::Null=>Type::Null,Value::Array(_)|Value::Map(_)=>Type::Unknown}}
impl IrProgram{pub fn text(&self)->String{let mut out=String::new();for f in &self.functions{out.push_str(&format!("function {}:\n",f.name));for i in &f.instructions{out.push_str(&format!("  {:?}\n",i));}}out}}
